import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.common.TopicPartition;
import org.apache.kafka.common.errors.WakeupException;
import org.apache.kafka.common.serialization.StringDeserializer;

public class ConsumerStopExperiment {
 static void require(boolean value,String message) { if(!value)throw new AssertionError(message); }
 public static void main(String[] args) throws Exception {
  Properties settings=new Properties();
  settings.put("bootstrap.servers",args[0]);settings.put("group.id","owned-stop-"+UUID.randomUUID());
  settings.put("key.deserializer",StringDeserializer.class.getName());settings.put("value.deserializer",StringDeserializer.class.getName());
  settings.put("enable.auto.commit","false");settings.put("default.api.timeout.ms","3000");
  KafkaConsumer<String,String> consumer=new KafkaConsumer<>(settings);
  AtomicBoolean stopping=new AtomicBoolean();AtomicReference<Throwable> failure=new AtomicReference<>();
  AtomicBoolean woke=new AtomicBoolean();AtomicLong closer=new AtomicLong(-1);CountDownLatch entered=new CountDownLatch(1),done=new CountDownLatch(1);
  TopicPartition partition=new TopicPartition(args[1],0);
  Thread owner=new Thread(()->{
   try {
    consumer.assign(List.of(partition));consumer.seek(partition,0);
    while(!stopping.get()) { entered.countDown();consumer.poll(Duration.ofSeconds(30)); }
   } catch(WakeupException expected) {
    if(!stopping.get())failure.set(new AssertionError("wakeup happened without published stop intent"));
    else woke.set(true);
   } catch(Throwable problem) { failure.set(problem); }
   finally {
    try { consumer.close(Duration.ofSeconds(2));closer.set(Thread.currentThread().getId()); }
    catch(Throwable problem) { failure.compareAndSet(null,problem); }
    done.countDown();
   }
  },"owned-consumer-thread");
  owner.start();
  try {
   require(entered.await(4,TimeUnit.SECONDS),"consumer owner did not enter polling");
   long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);boolean observedPoll=false;
   while(System.nanoTime()<deadline) {
    observedPoll=Arrays.stream(owner.getStackTrace()).anyMatch(frame->frame.getClassName().contains("KafkaConsumer")&&frame.getMethodName().equals("poll"));
    if(observedPoll)break;Thread.sleep(5);
   }
   require(observedPoll,"actual Kafka client poll frame was not observed");
   boolean ordinaryRejected=false;
   try { consumer.position(partition); }
   catch(ConcurrentModificationException expected) { ordinaryRejected=true; }
   require(ordinaryRejected,"fixture did not witness ordinary cross-thread client access rejection");
   System.out.println("NATIVE_KAFKA_JAVA_CONCURRENT_POSITION_REJECTED_WHILE_OWNER_POLLS");
   Throwable stopError=null;
   try { ConsumerStop.request(consumer,stopping); }catch(Throwable error) { stopError=error; }
   require(stopError==null,"cross-thread shutdown operation failed: "+stopError);
   require(done.await(1500,TimeUnit.MILLISECONDS),"stop request did not wake the actual bounded client poll");
   require(failure.get()==null,"owner failure: "+failure.get());
   require(stopping.get()&&woke.get(),"stop intent/wakeup completion missing");
   require(closer.get()==owner.getId(),"consumer close did not remain on its owner thread");
   System.out.println("NATIVE_KAFKA_JAVA_WAKEUP_CROSSES_THREADS_CLOSE_STAYS_WITH_OWNER");
  } finally {
   stopping.set(true);consumer.wakeup();owner.join(4000);
   require(!owner.isAlive(),"owned consumer thread leaked");
  }
 }
}
